{
    int n = 2;
    int a[n];
    n = 7;
    printf("%d %zu\n", n, sizeof a / sizeof a[0]);
    return 0;
}

#include <stdio.h>



int main(void)
{
    int n = 3;
    int a[n];
    for (int i = 0; i < n; i++) {
        a[i] = (i + 1) * (i + 1);
    }
    printf("%d\n", a[n - 1]);
    return 0;
}

#include <stdio.h>



int main(void)
{
    for (int n = 1; n <= 3; n++) {
        int a[n];
        printf("%zu\n", sizeof a / sizeof a[0]);
    }
    return 0;
}

